function apiOrigin() {
  return (process.env.ALPHALAB_API_ORIGIN || 'http://127.0.0.1:8000').replace(/\/+$/, '')
}

async function getStrategy(strategyId) {
  const response = await fetch(apiOrigin() + '/api/strategies/' + encodeURIComponent(strategyId), { headers: { Accept: 'application/json' } })
  if (!response.ok) throw new Error('AlphaLab strategy preflight ' + response.status + ': ' + await response.text())
  return response.json()
}

async function run(input) {
  const profile = input.profile === 'runtime' ? 'runtime' : 'demo'
  const strategyId = String(input.strategy_id || '').trim()
  if (!strategyId) throw new Error('strategy_id is required')
  const strategy = await getStrategy(strategyId)
  if (strategy.implementation === 'python') {
    if (!strategy.python_source_sha256) throw new Error('Python strategy source is missing or has no hash')
    if (input.confirm_python_execution !== true) throw new Error('Python strategy execution requires an explicit user request and confirm_python_execution=true')
  }
  const response = await fetch(apiOrigin() + '/api/backtests/run', {
    method: 'POST',
    headers: { Accept: 'application/json', 'Content-Type': 'application/json' },
    body: JSON.stringify({
      strategy_id: strategyId,
      start_date: String(input.start_date || '').trim(),
      end_date: String(input.end_date || '').trim(),
      profile,
    }),
  })
  if (!response.ok) throw new Error('AlphaLab API ' + response.status + ': ' + await response.text())
  const result = await response.json()
  if (strategy.implementation === 'python' && result.provenance?.strategy_python_sha256 !== strategy.python_source_sha256) {
    throw new Error('Python strategy source changed during backtest execution')
  }
  if (result.provenance?.strategy_python?.source) result.provenance.strategy_python = { sha256: result.provenance.strategy_python.sha256 }
  return { ...result, strategy_preflight: { strategy_type: strategy.strategy_type, implementation: strategy.implementation, python_source_sha256: strategy.python_source_sha256 || null } }
}
